with product_summary as (select product_id, round(avg(unit_price), 2) as avg_unit_price, sum(quantity * unit_price) as revenue from order_items group by product_id) select p.id, p.cost, p.category, ps.avg_unit_price, ps.revenue from products p inner join product_summary ps on p.id = ps.product_id where ps.avg_unit_price >= 73 order by cost;
